import numpy as np
I=np.array(G['Demo pair 1 input']); O=np.array(G['Demo pair 1 output'])
def comp(g,val):
    g=(g==val); seen=np.zeros_like(g,bool); out=[]
    H,W=g.shape
    for r in range(H):
        for c in range(W):
            if g[r,c] and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            xx,yy=x+dx,y+dy
                            if 0<=xx<H and 0<=yy<W and g[xx,yy] and not seen[xx,yy]:
                                seen[xx,yy]=True; st.append((xx,yy))
                out.append(cells)
    return out
